<?php require __DIR__.'/../config/app.php';$me=require_role('student');try{$q=db()->prepare('SELECT a.id,a.status,a.applied_at,e.title,e.event_date,e.category,e.venue FROM event_applications a JOIN events e ON e.id=a.event_id WHERE a.user_id=? ORDER BY a.applied_at DESC');$q->execute([$me['id']]);$rows=$q->fetchAll();}catch(Throwable $t){$rows=[];}$pageTitle='My Applications';$activePage='applications';$bodyClass='dashboard-page';$sidebarItems=[['Dashboard','student/dashboard.php','▦'],['Explore Events','events.php','⊙'],['My Applications','student/applications.php','♙'],['My Volunteering','student/volunteering.php','♧'],['My Cultural Activities','student/cultural-activities.php','♬'],['My Profile','student/profile.php','♙'],['Notifications','notifications.php','♧'],['Change Password','student/settings.php','⚙']];require __DIR__.'/../includes/header.php';?><div class="dash-layout"><?php require __DIR__.'/../includes/sidebar.php';?><main class="content-page admin-content"><h1>My Applications</h1><p>Track the status of your event applications.</p><div class="table-wrap"><table><thead><tr><th>Event</th><th>Category</th><th>Event date</th><th>Applied on</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['title'])?><small><?=e($r['venue'])?></small></td><td><?=e(ucfirst($r['category']))?></td><td><?=date('d M Y',strtotime($r['event_date']))?></td><td><?=date('d M Y',strtotime($r['applied_at']))?></td><td><span class="pill <?=strtolower(e($r['status']))?>"><?=e($r['status'])?></span></td></tr><?php endforeach;?></tbody></table></div><?php if(!$rows):?><div class="empty">No applications yet. <a href="<?=url('events.php')?>">Explore events →</a></div><?php endif;?></main></div><?php require __DIR__.'/../includes/footer.php';
